418	    /**
419	     * Read the {@code Idempotency-Key} header from the current request, or {@code null} when the
420	     * header is absent, blank, or no request is bound to the thread. The header is not part of the
421	     * generated API signature, so it is read from the ambient request rather than a method parameter.
422	     */
423	    private static String currentIdempotencyKey() {
424	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
425	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
426	            return null;
427	        }
428	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
429	        return isBlank(key) ? null : key;
430	    }
431	
432	    private static boolean isBlank(String value) {
433	        return value == null || value.trim().isEmpty();
434	    }
435	
436	    /**
437	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
438	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
439	     * compared case-insensitively with collapsed whitespace.
440	     */
441	    private static String collapse(String value) {
442	        if (value == null) {
443	            return "";
444	        }
445	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
446	    }
447	
448	    /**
449	     * Common street-type abbreviations expanded during address normalization.
450	     */
451	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
452	        "ST", "STREET",
453	        "RD", "ROAD",
454	        "AVE", "AVENUE");
455	
456	    /**
457	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
458	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
459	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
460	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
461	     * address maps to itself.
462	     */
463	    private static String normalizeAddress(String value) {
464	        if (value == null) {
465	            return "";
466	        }
467	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
468	        if (collapsed.isEmpty()) {
469	            return "";
470	        }
471	        String[] tokens = collapsed.split(" ");
472	        StringBuilder sb = new StringBuilder(collapsed.length());
473	        for (int i = 0; i < tokens.length; i++) {
474	            if (i > 0) {
475	                sb.append(' ');
476	            }
477	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
478	        }
479	        return sb.toString();
480	    }
481	
482	    /**
483	     * Derive the stable household identifier shared by owners with the same normalized last name
484	     * and postcode. It is a deterministic function of those two values, so every member of a
485	     * household independently derives the same identifier: the first 12 upper-case hex characters
486	     * of {@code SHA-256(normalizedLastName + '|' + postcode)}. A {@code null} postcode contributes
487	     * an empty segment.
488	     */
489	    private static String householdId(String normalizedLastName, String postcode) {
490	        try {
491	            byte[] digest = MessageDigest.getInstance("SHA-256")
492	                .digest((normalizedLastName + "|" + (postcode == null ? "" : postcode))
493	                    .getBytes(StandardCharsets.UTF_8));
494	            StringBuilder sb = new StringBuilder(digest.length * 2);
495	            for (byte b : digest) {
496	                sb.append(String.format("%02x", b));
497	            }
498	            return sb.substring(0, 12).toUpperCase();
499	        }
500	        catch (NoSuchAlgorithmException e) {
501	            throw new IllegalStateException("SHA-256 not available", e);
502	        }
503	    }
504	
505	    /**
506	     * Derive the identity key into which all duplicate detection is consolidated:
507	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A null email or
508	     * household id contributes an empty segment. Two owners are duplicates only when their whole
509	     * identity keys are equal.
510	     */
511	    private static String identityKey(String telephone, String email, String householdId) {
512	        return (telephone == null ? "" : telephone)
513	            + "|" + (email == null ? "" : email)
514	            + "|" + (householdId == null ? "" : householdId);
515	    }
516	
517	    /**
518	     * Count the existing owners that share the given first and last name, compared
519	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
520	     * namesakes that already existed at creation time (the new owner itself is not included).
521	     */
522	    private int countNamesakes(String firstName, String lastName) {
523	        return (int) this.clinicService.findAllOwners().stream()
524	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
525	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
526	                && existing.getLastName().equalsIgnoreCase(lastName))
527	            .count();
528	    }
529	
530	    /**
531	     * Count the existing owners that already belong to the given household (i.e. carry the same
532	     * non-null householdId). Called after any existing members have been backfilled with the shared
533	     * identifier but before the new owner is saved, so the returned value reflects the members that
534	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
535	     * new owner is not part of any household ({@code householdId} is null).
536	     */
537	    private int countHouseholdMembers(String householdId) {
538	        if (householdId == null) {
539	            return 0;
540	        }
541	        return (int) this.clinicService.findAllOwners().stream()
542	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
543	            .count();
544	    }
545	
546	    /**
547	     * Find an existing owner that this new owner is a possible (soft) duplicate of: one that shares
548	     * the new owner's last name (compared case-insensitively) and postcode while carrying a different
549	     * (already normalized) telephone. When several existing owners match, the earliest (lowest id) is
550	     * returned so the result is deterministic. Returns {@code null} when there is no such owner —
551	     * including when the new owner has no last name or postcode, since a shared postcode is required
552	     * to match.
553	     */
554	    private Owner findPossibleDuplicate(String lastName, String postcode, String normalizedTelephone) {
555	        if (isBlank(lastName) || isBlank(postcode)) {
556	            return null;
557	        }
558	        return this.clinicService.findAllOwners().stream()
559	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
560	            .filter(existing -> postcode.equals(existing.getPostcode()))
561	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
562	            .min(java.util.Comparator.comparing(Owner::getId))
563	            .orElse(null);
564	    }
