566	    /**
567	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
568	     * request to create another owner in it is rejected as a conflict.
569	     */
570	    private static final int MAX_OWNERS_PER_CITY = 50;
571	
572	    /**
573	     * Count the existing owners registered in the given city, compared case-insensitively (as in
574	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
575	     * reflects the owners that already existed at creation time.
576	     */
577	    private int countOwnersInCity(String city) {
578	        return (int) this.clinicService.findAllOwners().stream()
579	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
580	            .count();
581	    }
