583	    /**
584	     * The maximum number of owners that may be created on a single day. Once this many owners
585	     * already carry a given day's registration date, a request to create another owner that day is
586	     * rejected with a 429.
587	     */
588	    private static final int MAX_OWNERS_PER_DAY = 100;
589	
590	    /**
591	     * The number of owners that may be created on a single day before the bulk-signup warning is
592	     * flagged. Once more than this many owners already carry a given day's registration date, a
593	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
594	     */
595	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
596	
597	    /**
598	     * Count the existing owners whose registration date is the given day. Called before the new
599	     * owner is saved, so the returned value reflects the owners that already existed at creation
600	     * time.
601	     */
602	    private int countOwnersRegisteredOn(LocalDate date) {
603	        return (int) this.clinicService.findAllOwners().stream()
604	            .filter(existing -> date.equals(existing.getRegistrationDate()))
605	            .count();
606	    }
607	
608	    /** Fixed public holidays the business-day roll skips. */
609	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
610	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
611	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
612	
613	    /**
614	     * Roll a date forward onto a business day: Saturdays, Sundays and listed public holidays are
615	     * advanced one day at a time until a non-weekend, non-holiday day is reached, while an ordinary
616	     * business day is returned unchanged. Used so the effective registration date (whether supplied
617	     * or defaulted) always falls on a business day.
618	     */
619	    private static LocalDate toBusinessDay(LocalDate date) {
620	        while (isWeekendOrHoliday(date)) {
621	            date = date.plusDays(1);
622	        }
623	        return date;
624	    }
625	
626	    private static boolean isWeekendOrHoliday(LocalDate date) {
627	        return switch (date.getDayOfWeek()) {
628	            case SATURDAY, SUNDAY -> true;
629	            default -> PUBLIC_HOLIDAYS.contains(date);
630	        };
631	    }
632	
633	    /**
634	     * Build the customer code for a new owner: {@code '<REGION>-<HASH8>'} where REGION is the region
635	     * derived from the owner's postcode/city and HASH8 is the first 8 upper-case hex characters of
636	     * {@code SHA-256(normalizedTelephone + lastName)} (e.g. {@code 'NSW-1A2B3C4D'}).
637	     */
638	    private static String customerCode(String region, String normalizedTelephone, String lastName) {
639	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
640	    }
641	
642	    /**
643	     * Ensure the computed customer code is unique across existing owners. When {@code base} is
644	     * already free it is returned unchanged; otherwise {@code '-<n>'} is appended using the smallest
645	     * {@code n} of 2 or more that produces a value no existing owner already carries.
646	     */
647	    private String deduplicateCustomerCode(String base) {
648	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
649	            .map(Owner::getCustomerCode)
650	            .filter(java.util.Objects::nonNull)
651	            .collect(java.util.stream.Collectors.toSet());
652	        if (!inUse.contains(base)) {
653	            return base;
654	        }
655	        int n = 2;
656	        while (inUse.contains(base + "-" + n)) {
657	            n++;
658	        }
659	        return base + "-" + n;
660	    }
661	
662	    /**
663	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
664	     */
665	    private static String hash8(String input) {
666	        try {
667	            byte[] digest = MessageDigest.getInstance("SHA-256")
668	                .digest(input.getBytes(StandardCharsets.UTF_8));
669	            StringBuilder sb = new StringBuilder(digest.length * 2);
670	            for (byte b : digest) {
671	                sb.append(String.format("%02x", b));
672	            }
673	            return sb.substring(0, 8).toUpperCase();
674	        }
675	        catch (NoSuchAlgorithmException e) {
676	            throw new IllegalStateException("SHA-256 not available", e);
677	        }
678	    }
679	
680	    /**
681	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
682	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
683	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
684	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
685	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
686	     * always agree.
687	     */
688	    private static String deriveRegion(String postcode, String city) {
689	        if (postcode != null && postcode.matches("\\d{4}")) {
690	            int value = Integer.parseInt(postcode);
691	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
692	                int[] range = entry.getValue();
693	                if (value >= range[0] && value <= range[1]) {
694	                    return entry.getKey();
695	                }
696	            }
697	        }
698	        if (city == null) {
699	            return "UNKNOWN";
700	        }
701	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
702	    }
703	
704	    /**
705	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
706	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
707	     * and accepts any 4-digit postcode.
708	     */
709	    private static final Map<String, String> CITY_REGION = Map.of(
710	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
711	
712	    /**
713	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
714	     * Each entry is a two-element {@code {low, high}} array.
715	     */
716	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
717	        "NSW", new int[] {2000, 2099},
718	        "VIC", new int[] {3000, 3099},
719	        "QLD", new int[] {4000, 4099});
720	
721	    /**
722	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
723	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
724	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
725	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
726	     * 4-digit postcode. A malformed or out-of-range postcode throws an
727	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
728	     */
729	    private static void validatePostcode(String city, String postcode) {
730	        if (postcode == null || postcode.isEmpty()) {
731	            return;
732	        }
733	        if (!postcode.matches("\\d{4}")) {
734	            throw new InvalidOwnerFieldsException(List.of("postcode"));
735	        }
736	        String region = city == null ? null : CITY_REGION.get(city);
737	        if (region == null) {
738	            return;
739	        }
740	        int[] range = REGION_POSTCODES.get(region);
741	        int value = Integer.parseInt(postcode);
742	        if (value < range[0] || value > range[1]) {
743	            throw new InvalidOwnerFieldsException(List.of("postcode"));
744	        }
745	    }
746	
747	    /**
748	     * Required national-number length for each E.164 country calling code we validate: a
749	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
750	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
751	     */
752	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
753	        "1", 10,
754	        "61", 9);
755	
756	    /**
757	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
758	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
759	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
760	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
761	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
762	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
763	     * rejected with a 400.
764	     */
765	    private static String toE164(String raw) {
766	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
767	        boolean hasCountryCode = cleaned.startsWith("+");
768	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
769	        if (!digits.matches("\\d+")) {
770	            throw new InvalidOwnerFieldsException(List.of("telephone"));
771	        }
772	        if (!hasCountryCode) {
773	            if (digits.startsWith("0")) {
774	                digits = digits.substring(1);
775	            }
776	            digits = "61" + digits;
777	        }
778	        if (digits.length() < 8 || digits.length() > 15) {
779	            throw new InvalidOwnerFieldsException(List.of("telephone"));
780	        }
781	        // For a recognised country code, the national number (the digits after the code) must be
782	        // exactly the expected length for that country. Match the longest known code so a shorter
783	        // code that is a prefix of another cannot mask it.
784	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
785	            if (digits.length() <= codeLength) {
786	                continue;
787	            }
788	            String countryCode = digits.substring(0, codeLength);
789	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
790	            if (requiredNationalLength != null) {
791	                if (digits.length() - codeLength != requiredNationalLength) {
792	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
793	                }
794	                break;
795	            }
796	        }
797	        return "+" + digits;
798	    }
799	
800	    /**
801	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
802	     * and a domain with at least one dot-separated label, none of which contain whitespace or
803	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
804	     */
805	    private static final Pattern EMAIL_PATTERN =
806	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
807	
808	    /**
809	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
810	     * after the {@code @}, compared case-insensitively) is on this blocklist is rejected with a 400.
811	     */
812	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
813	        "mailinator.com", "tempmail.com", "guerrillamail.com");
814	
815	    /**
816	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
817	     * supplied (the field is optional). When supplied it must be a syntactically valid address whose
818	     * domain is not on the disposable-domain blocklist, otherwise an
819	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400. A valid
820	     * address is returned lower-cased.
821	     */
822	    private static String normalizeEmail(String email) {
823	        if (email == null || email.isEmpty()) {
824	            return null;
825	        }
826	        String trimmed = email.trim();
827	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
828	            throw new InvalidOwnerFieldsException(List.of("email"));
829	        }
830	        String normalized = trimmed.toLowerCase();
831	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
832	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
833	            throw new InvalidOwnerFieldsException(List.of("email"));
834	        }
835	        return normalized;
836	    }
837	}
